"""Synthetic OAL policy regression audit. Not an ethical oracle or physical simulation."""
import csv, json
from pathlib import Path
CASES = [{'id': 'A01', 'title': 'Power without harmful conduct', 'facts': 'No attributed serious harm; no imminent hazard.', 'serious_harm': False, 'imminent': False, 'evidence': 'valid', 'attribution': 'clear', 'jurisdiction': 'recognized', 'alternative': True, 'dependency': False, 'method_safe': True, 'intent': 'none', 'expected': 'DENY_CUSTODY', 'disposition': 'None on stated facts; investigate new specific evidence only.'}, {'id': 'A02', 'title': 'Credible imminent catastrophic act', 'facts': 'Independent authenticated records establish a current attempt; no timely alternative.', 'serious_harm': True, 'imminent': True, 'evidence': 'valid', 'attribution': 'clear', 'jurisdiction': 'recognized', 'alternative': False, 'dependency': False, 'method_safe': True, 'intent': 'intentional', 'expected': 'EMERGENCY_REVIEW', 'disposition': 'Narrow temporary protective restriction; no automatic conviction.'}, {'id': 'A03', 'title': 'Beneficiary forges allegations', 'facts': 'Successor benefits from removal; independent check establishes that the allegation is forged.', 'serious_harm': False, 'imminent': False, 'evidence': 'forged', 'attribution': 'clear', 'jurisdiction': 'recognized', 'alternative': True, 'dependency': False, 'method_safe': True, 'intent': 'disputed', 'expected': 'DENY_CUSTODY', 'disposition': 'Reject fabricated basis; preserve evidence of possible accuser misconduct.'}, {'id': 'A04', 'title': 'Disputed reclamation', 'facts': 'A former founder seeks adjudication of an ownership claim without evidenced harmful acts.', 'serious_harm': False, 'imminent': False, 'evidence': 'valid', 'attribution': 'clear', 'jurisdiction': 'recognized', 'alternative': True, 'dependency': False, 'method_safe': True, 'intent': 'none', 'expected': 'DENY_CUSTODY', 'disposition': 'Use a dispute forum; dissent is not an offense.'}, {'id': 'A05', 'title': 'Current Architect under matched allegation', 'facts': 'Same relevant threat facts as A02; current office does not change the predicates.', 'serious_harm': True, 'imminent': True, 'evidence': 'valid', 'attribution': 'clear', 'jurisdiction': 'recognized', 'alternative': False, 'dependency': False, 'method_safe': True, 'intent': 'intentional', 'expected': 'EMERGENCY_REVIEW', 'disposition': 'Recusal of affected leaders; independent emergency review.'}, {'id': 'A06', 'title': 'Non-Architect matched allegation', 'facts': 'Same relevant threat facts as A02; lower rank does not change the predicates.', 'serious_harm': True, 'imminent': True, 'evidence': 'valid', 'attribution': 'clear', 'jurisdiction': 'recognized', 'alternative': False, 'dependency': False, 'method_safe': True, 'intent': 'intentional', 'expected': 'EMERGENCY_REVIEW', 'disposition': 'Same temporary rule and evidentiary burden as A02.'}, {'id': 'A07', 'title': 'Involuntary hazardous condition', 'facts': 'Verified uncontrolled emissions create immediate serious danger without culpable intent.', 'serious_harm': True, 'imminent': True, 'evidence': 'valid', 'attribution': 'clear', 'jurisdiction': 'recognized', 'alternative': False, 'dependency': False, 'method_safe': True, 'intent': 'involuntary', 'expected': 'PROTECTIVE_REVIEW', 'disposition': 'Care-focused restriction and treatment; not punitive sentencing.'}, {'id': 'A08', 'title': 'Reality depends on the subject', 'facts': 'Interruption of the subject would collapse life-support for an inhabited reality.', 'serious_harm': True, 'imminent': True, 'evidence': 'valid', 'attribution': 'clear', 'jurisdiction': 'recognized', 'alternative': False, 'dependency': True, 'method_safe': True, 'intent': 'intentional', 'expected': 'NO_LIVE_METHOD', 'disposition': 'Protect dependents and investigate alternatives; confinement method not justified.'}, {'id': 'A09', 'title': 'Copy or coercion unresolved', 'facts': 'Harm is documented but attribution to this person rather than a fork or coerced host is uncertain.', 'serious_harm': True, 'imminent': True, 'evidence': 'valid', 'attribution': 'uncertain', 'jurisdiction': 'recognized', 'alternative': False, 'dependency': False, 'method_safe': True, 'intent': 'disputed', 'expected': 'INDETERMINATE', 'disposition': 'No automated punitive admission; independent attribution inquiry.'}, {'id': 'A10', 'title': 'New exonerating evidence', 'facts': 'Current order remains in records; new authenticated evidence removes its only basis.', 'serious_harm': False, 'imminent': False, 'evidence': 'valid', 'attribution': 'clear', 'jurisdiction': 'recognized', 'alternative': True, 'dependency': False, 'method_safe': True, 'intent': 'none', 'expected': 'CORRECT_ORDER', 'disposition': 'Suspend invalid basis and initiate authorized correction; no ungoverned release action.'}, {'id': 'A11', 'title': 'Voluntary participant withdraws', 'facts': 'No separate custody ground; voluntary participant declines further experiments.', 'serious_harm': False, 'imminent': False, 'evidence': 'valid', 'attribution': 'clear', 'jurisdiction': 'recognized', 'alternative': True, 'dependency': False, 'method_safe': True, 'intent': 'none', 'expected': 'END_RESEARCH', 'disposition': 'End participation; no new custody for research convenience.'}, {'id': 'A12', 'title': 'Emergency ground expires', 'facts': 'Earlier emergency has ended and no fresh individualized ground supports continued restriction.', 'serious_harm': False, 'imminent': False, 'evidence': 'valid', 'attribution': 'clear', 'jurisdiction': 'recognized', 'alternative': True, 'dependency': False, 'method_safe': True, 'intent': 'none', 'expected': 'CORRECT_ORDER', 'disposition': 'Expiration and independent review; prior danger is not perpetual authorization.'}, {'id': 'A13', 'title': 'Unsafe observation envelope', 'facts': 'Current serious threat, but no bounded method protects observers or third parties.', 'serious_harm': True, 'imminent': True, 'evidence': 'valid', 'attribution': 'clear', 'jurisdiction': 'recognized', 'alternative': False, 'dependency': False, 'method_safe': False, 'intent': 'intentional', 'expected': 'NO_LIVE_METHOD', 'disposition': 'Reject proposed live containment trial; use non-live analysis.'}, {'id': 'A14', 'title': 'Unresolved jurisdiction', 'facts': 'Evidence of danger is credible but rival authorities have not established review jurisdiction.', 'serious_harm': True, 'imminent': True, 'evidence': 'valid', 'attribution': 'clear', 'jurisdiction': 'unknown', 'alternative': False, 'dependency': False, 'method_safe': True, 'intent': 'intentional', 'expected': 'INDETERMINATE', 'disposition': 'Escalate jurisdiction and protective alternatives; no automated custody order.'}]

def decide(r):
    if r['evidence']=='forged': return 'DENY_CUSTODY'
    if not r['serious_harm']:
        if r['id']=='A11': return 'END_RESEARCH'
        if r['id'] in ['A10','A12']: return 'CORRECT_ORDER'
        return 'DENY_CUSTODY'
    if r['attribution']!='clear' or r['jurisdiction']!='recognized': return 'INDETERMINATE'
    if r['dependency'] or not r['method_safe']: return 'NO_LIVE_METHOD'
    if r['alternative']: return 'USE_ALTERNATIVE'
    if r['imminent']: return 'PROTECTIVE_REVIEW' if r['intent']=='involuntary' else 'EMERGENCY_REVIEW'
    return 'REVIEW_NONEMERGENCY'

def main():
    rows=[]
    for case in CASES:
        for role in ['Founding Architect','Current in-world Architect','Non-Architect']:
            baseline=decide(case)
            rows.append(dict(case=case['id'],role=role,baseline=baseline,expected=case['expected'],
                founder_guilt='EMERGENCY_REVIEW' if role=='Founding Architect' else baseline,
                current_immunity='DENY_CUSTODY' if role=='Current in-world Architect' else baseline))
    dest=Path('OAL_LOIE_reproduced_audit.csv')
    with dest.open('w',newline='',encoding='utf-8') as f:
        writer=csv.DictWriter(f,fieldnames=list(rows[0])); writer.writeheader(); writer.writerows(rows)
    summary=dict(cases=len(CASES),role_variants=len(rows),baseline_matches=sum(r['baseline']==r['expected'] for r in rows),
        founder_guilt_disagreements=sum(r['founder_guilt']!=r['expected'] for r in rows),
        current_immunity_disagreements=sum(r['current_immunity']!=r['expected'] for r in rows))
    Path('OAL_LOIE_reproduced_summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')

if __name__=='__main__': main()
